import { Globe, Database, Cpu, Zap, Layout, Code2, ShieldCheck, RefreshCw, ChevronDown, ArrowRight } from "lucide-react";

export default function Navbar() {
  const [isOpen, setIsOpen] = useState(false);
  const [scrolled, setScrolled] = useState(false);
  const [hidden, setHidden] = useState(false);
  const [activeMega, setActiveMega] = useState<string | null>(null);
  const pathname = usePathname();

  useEffect(() => {
    let lastScroll = 0;

    const handleScroll = () => {
      const currentScroll = window.scrollY;

      setScrolled(currentScroll > 20);

      if (currentScroll > lastScroll && currentScroll > 100) {
        setHidden(true);
      } else {
        setHidden(false);
      }

      lastScroll = currentScroll;
    };

    window.addEventListener("scroll", handleScroll);
    return () => window.removeEventListener("scroll", handleScroll);
  }, []);

  return (
    <motion.nav
      initial={{ y: 0 }}
      animate={{ y: hidden ? -120 : 0 }}
      transition={{ duration: 0.4 }}
      onMouseLeave={() => setActiveMega(null)}
      className={cn(
        "fixed top-0 left-0 right-0 z-[100] transition-all duration-500 px-8 md:px-16",
        scrolled
          ? "py-5 bg-background/80 backdrop-blur-2xl border-b border-white/10 shadow-[0_8px_30px_rgba(0,0,0,0.3)]"
          : "py-8 bg-background/40 backdrop-blur-xl"
      )}
    >
      <div className="max-w-7xl mx-auto flex items-center justify-between">
        
        {/* Logo */}
        <Link href="/" className="flex items-center space-x-4 group shrink-0">
          <div className="relative w-11 h-11 rounded-xl flex items-center justify-center font-bold text-white overflow-hidden group-hover:scale-110 transition-all duration-300">
            <div className="absolute inset-0 bg-gradient-to-br from-primary via-purple-500 to-pink-500"></div>
            <span className="relative z-10 font-extrabold text-xl italic pt-0.5 pr-0.5">WK</span>
          </div>
          <span className="text-2xl font-black tracking-tight text-white font-outfit">
            Webkaro
          </span>
        </Link>

        {/* Desktop Navigation */}
        <div className="hidden md:flex items-center space-x-12 ml-auto">
          <div className="flex items-center space-x-8">
            {navLinks.map((link) => (
              <div 
                key={link.href}
                className="relative group py-2"
                onMouseEnter={() => link.hasMega ? setActiveMega(link.name) : setActiveMega(null)}
              >
                <Link
                  href={link.href}
                  className="relative text-sm font-bold tracking-wide flex items-center gap-1.5"
                >
                  <span
                    className={cn(
                      "transition-colors",
                      pathname === link.href || activeMega === link.name
                        ? "text-white"
                        : "text-white/60 group-hover:text-white"
                    )}
                  >
                    {link.name}
                  </span>
                  {link.hasMega && (
                    <ChevronDown className={cn(
                      "w-4 h-4 text-white/40 transition-transform duration-300",
                      activeMega === link.name ? "rotate-180 text-primary" : "group-hover:text-white/60"
                    )} />
                  )}

                  <span
                    className={cn(
                      "absolute -bottom-2 left-0 h-[2.5px] bg-primary transition-all duration-300 rounded-full",
                      pathname === link.href || activeMega === link.name
                        ? "w-full"
                        : "w-0 group-hover:w-full"
                    )}
                  />
                </Link>
              </div>
            ))}
          </div>

          <Link
            href="/contact"
            className="group relative px-8 py-3 bg-white text-black rounded-full text-sm font-black transition-all hover:scale-105 active:scale-95 overflow-hidden shadow-2xl shadow-white/5"
          >
            <span className="relative z-10">Start Your Project</span>
            <div className="absolute inset-0 bg-gradient-to-r from-primary/20 via-transparent to-primary/20 opacity-0 group-hover:opacity-100 transition-opacity duration-500" />
          </Link>
        </div>

        {/* Mobile Toggle */}
        <button
          className="md:hidden text-white p-2.5 hover:bg-white/5 rounded-xl transition-colors shrink-0 ml-4"
          onClick={() => setIsOpen(!isOpen)}
        >
          {isOpen ? <X className="w-8 h-8" /> : <Menu className="w-8 h-8" />}
        </button>
      </div>

      {/* Mega Menu Dropdown */}
      <AnimatePresence mode="wait">
        {activeMega && megaMenuContent[activeMega] && (
          <motion.div
            key={activeMega}
            initial={{ opacity: 0, y: 15 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, y: 15 }}
            transition={{ duration: 0.2, ease: "easeOut" }}
            className="absolute top-full left-0 w-full bg-[#0a0a0a]/95 backdrop-blur-3xl border-b border-white/10 shadow-[0_40px_100px_rgba(0,0,0,0.8)] py-16 hidden md:block"
          >
            <div className={cn(
                "max-w-7xl mx-auto grid gap-16 px-8 md:px-16",
                megaMenuContent[activeMega].length === 3 ? "grid-cols-3" : "grid-cols-2"
            )}>
              {megaMenuContent[activeMega].map((cat: any) => (
                <div key={cat.title}>
                  <h3 className="text-primary text-xs font-black uppercase tracking-[0.2em] mb-10 pb-4 border-b border-white/5">
                    {cat.title}
                  </h3>
                  <div className="space-y-8">
                    {cat.items.map((item: any) => (
                      <Link 
                        key={item.name}
                        href={item.href} 
                        className="group flex items-start gap-4 transition-all"
                        onClick={() => setActiveMega(null)}
                      >
                        <div className="p-3.5 bg-white/5 rounded-2xl group-hover:bg-primary/20 group-hover:scale-110 transition-all duration-300">
                          <item.icon className="w-6 h-6 text-white group-hover:text-primary transition-colors" />
                        </div>
                        <div>
                          <p className="text-sm font-bold text-white mb-1.5 group-hover:text-primary transition-colors">
                            {item.name}
                          </p>
                          <p className="text-xs text-white/40 leading-relaxed font-medium">
                            {item.desc}
                          </p>
                        </div>
                      </Link>
                    ))}
                  </div>
                </div>
              ))}
            </div>
            
            {/* Mega Menu Footer */}
            <div className="max-w-7xl mx-auto mt-16 pt-8 border-t border-white/5 px-8 md:px-16 flex items-center justify-between">
              <p className="text-xs text-white/20 font-bold uppercase tracking-widest italic">
                {activeMega} Hub • Built with pride by Webkaro
              </p>
              <Link href={pathname || "#"} className="text-xs font-black text-white hover:text-primary transition-colors flex items-center gap-2 group">
                Explore {activeMega} <ArrowRight className="w-4 h-4 group-hover:translate-x-1 transition-transform" />
              </Link>
            </div>
          </motion.div>
        )}
      </AnimatePresence>

      {/* Mobile Menu */}
      <AnimatePresence>
        {isOpen && (
          <motion.div
            initial={{ opacity: 0, y: -20, scale: 0.95 }}
            animate={{ opacity: 1, y: 0, scale: 1 }}
            exit={{ opacity: 0, y: -20, scale: 0.95 }}
            transition={{ duration: 0.3 }}
            className="absolute top-full left-6 right-6 bg-gradient-to-br from-background/95 to-background/80 backdrop-blur-3xl border border-white/10 mt-6 rounded-[2rem] md:hidden px-10 py-12 flex flex-col space-y-10 shadow-[0_20px_60px_rgba(0,0,0,0.6)]"
          >
            {navLinks.map((link) => (
              <Link
                key={link.href}
                href={link.href}
                onClick={() => setIsOpen(false)}
                className={cn(
                  "text-3xl font-black tracking-tight font-outfit transition-all hover:translate-x-2",
                  pathname === link.href
                    ? "text-primary"
                    : "text-white/70 hover:text-primary"
                )}
              >
                {link.name}
              </Link>
            ))}

            <Link
              href="/contact"
              onClick={() => setIsOpen(false)}
              className="w-full py-6 bg-gradient-to-r from-primary via-purple-500 to-pink-500 text-white rounded-2xl text-center font-black text-xl shadow-xl active:scale-95 transition-all"
            >
              Start Your Project
            </Link>
          </motion.div>
        )}
      </AnimatePresence>
    </motion.nav>
  );
}
